mapper.select:
SELECT FTA_CODE , FTA_NAME , EFFECT_DATE , FTA_STATUS , (SELECT COUNT(*) FROM FTA_APPLY_NATION T WHERE T.FTA_CODE = A.FTA_CODE) AS FTA_APPLY_CNT , CO_ISSUE_FLAG , DE_MINIMIS_RATE , RVC_RATE , DELETE_YN , INKOTERMS_TYPE , COVER_YN FROM FTA_MASTER A WHERE COMPANY_CODE = #{company_code}
AND A.FTA_CODE = #{searchFtaCode}
AND EXISTS (SELECT 1 FROM FTA_APPLY_NATION B INNER JOIN CODE_DTL D ON B.NATION_CODE = D.CODE AND D.CATEGORY = 'NA' AND D.COMPANY_CODE = #{company_code} WHERE A.FTA_CODE = B.FTA_CODE AND (B.NATION_CODE LIKE CONCAT(#{searchCountry} , '%') OR D.CODE_NAME LIKE CONCAT(#{searchCountry} , '%')))
ORDER BY FTA_CODE

