mapper.update:
	UPDATE FTA_MASTER
	   SET FTA_NAME = #{fta_name}
	     , EFFECT_DATE = #{effect_date}
	     , FTA_STATUS = #{fta_status}
	     , CO_ISSUE_FLAG = #{co_issue_flag}
	     , DE_MINIMIS_RATE = #{de_minimis_rate}
	     , RVC_RATE = #{rvc_rate}
	     , COM_DE_MINIMIS_RATE = #{de_minimis_rate}
	     , COM_RVC_RATE = #{rvc_rate}
	     , DELETE_YN = #{delete_yn}
	     , INKOTERMS_TYPE = #{inkoterms_type}
	     , COVER_YN = #{cover_yn}
	     , UPDATE_DATE = NOW()
	     , UPDATE_BY = #{update_by}
     WHERE COMPANY_CODE = #{company_code}
	   AND FTA_CODE = #{fta_code}

mapper.delete:
DELETE FROM FTA_MASTER
WHERE COMPANY_CODE = #{company_code}
  AND FTA_CODE = #{fta_code}

